// Minimal hand-written stub of @opentelemetry/api, enough for the checker to
// resolve Tracer/Span identities from a fixture.
export interface Span {
  end(): void;
  setAttribute(key: string, value: unknown): Span;
}
export interface Tracer {
  startSpan(name: string): Span;
  startActiveSpan<T>(name: string, fn: (span: Span) => T): T;
}
export declare const trace: { getTracer(name: string): Tracer };
